INSERT INTO evidence_assertions (id, subject_type, subject_id, field_key, claimed_value_json, source_snapshot_id, evidence_quote, valid_from, valid_until, verification_status, verified_at) VALUES ('evidence_915bed1410489312e8d17218', 'PLACE', 'place_407a39fe34ebb4813bd96ec7', 'source_attributes', '{"retailType":"MARKET_UNCLASSIFIED","description":"臺北市公有士林市場原位於文林路、大南路與基河路所涵蓋的街區中段處，正對面即為慈諴宮，該市場創建於民國2年，至今逾百年歷史。鑑於市場主體建築年代已久，傳統零售市場之軟硬體設備及整體營運素質亦有轉型之必要，臺北市政府爰於87年積極策劃士林市場改建，91年11月拆除原舊市場，將原士林市場攤商暫遷至未來台北藝術中心預定地之臨時攤棚營業。改建工程已於100年完成，士…","inventoryPriceAvailable":false}', 'snapshot_333dc67bff07584aba1d65b4', '臺北市公有士林市場：{"retailType":"MARKET_UNCLASSIFIED","description":"臺北市公有士林市場原位於文林路、大南路與基河路所涵蓋的街區中段處，正對面即為慈諴宮，該市場創建於民國2年，至今逾百年歷史。鑑於市場主體建築年代已久，傳統零售市場之軟硬體設備及整體營運素質亦有轉型之必要，臺北市政府爰於87年積極策劃士林市場改建，91年11月拆除原舊市場，將原士…', NULL, NULL, 'OFFICIAL_CONFIRMED', '2026-09-05T12:32:21.384Z') ON CONFLICT (id) DO UPDATE SET subject_type=excluded.subject_type, subject_id=excluded.subject_id, field_key=excluded.field_key, claimed_value_json=excluded.claimed_value_json, source_snapshot_id=excluded.source_snapshot_id, evidence_quote=excluded.evidence_quote, valid_from=excluded.valid_from, valid_until=excluded.valid_until, verification_status=excluded.verification_status, verified_at=excluded.verified_at;
